function shopFail(){const w=q('#shopWallet');w.classList.add('poor');w.firstChild.textContent='SUCATA INSUFICIENTE ';setTimeout(()=>{w.classList.remove('poor');w.firstChild.textContent='SUCATA DISPONÍVEL '},900)}
function buyFrame(id){const f=FRAMES.find(x=>x.c===id);if(!career.ownedFrames.includes(id)){if(career.scrap<f.price)return shopFail();career.scrap-=f.price;career.ownedFrames.push(id)}career.selectedFrame=id;saveProgress();updateCareer();renderShop()}
function buyTrack(id){const t=TRACK_INFO[id];if(!career.ownedTracks.includes(id)){if(career.scrap<t.price)return shopFail();career.scrap-=t.price;career.ownedTracks.push(id)}career.selectedTrack=id;saveProgress();updateCareer();renderShop()}
function renderShop(){q('#shopScrap').textContent=career.scrap;const fg=q('#frameShop'),mg=q('#musicShop');fg.innerHTML='';mg.innerHTML='';fg.append(shopItem('MODO ALEATÓRIO','Alterna entre suas molduras.','#ffe3a0',{owned:true,selected:career.selectedFrame==='random'},0,()=>{career.selectedFrame='random';saveProgress();renderShop()}));FRAMES.forEach(f=>fg.append(shopItem(f.n,'Moldura 3D para a mesa.',f.color,{owned:career.ownedFrames.includes(f.c),selected:career.selectedFrame===f.c},f.price,()=>buyFrame(f.c))));mg.append(shopItem('MODO ALEATÓRIO','Alterna entre suas trilhas.','#ffe3a0',{owned:true,selected:career.selectedTrack===-1},0,()=>{career.selectedTrack=-1;saveProgress();renderShop()}));TRACK_INFO.forEach((t,i)=>mg.append(shopItem(t.n,t.note,t.color,{owned:career.ownedTracks.includes(i),selected:career.selectedTrack===i},t.price,()=>buyTrack(i))))}
function openShop(){renderShop();q('#shopModal').classList.remove('hidden')}
function closeShop(){q('#shopModal').classList.add('hidden')}
function renderContracts(){const grid=q('#contractGrid');grid.innerHTML='';CONTRACTS.forEach(c=>{const b=document.createElement('button'),selected=career.selectedContract===c.id;b.className='contract-card '+(selected?'selected':'');b.innerHTML=`<small>${c.rank}</small><b>${c.n}</b><span>${c.desc}</span><em>${selected?'✓ SELECIONADO':'+'+c.reward+' SUCATA'}</em>`;b.onclick=()=>{career.selectedContract=c.id;saveProgress();renderContracts()};grid.append(b)});const c=CONTRACTS.find(x=>x.id===career.selectedContract);q('#contractSelected').textContent=c.n+' • BÔNUS +'+c.reward}
function openContracts(){renderContracts();q('#contractModal').classList.remove('hidden')}
function closeContracts(){q('#contractModal').classList.add('hidden')}
function contractDone(won){if(!won)return false;switch(career.selectedContract){case'production':return matchStats.maxScore>=35;case'signature':return matchStats.friendPlayed;case'perfect':return wins===2&&losses===0;default:return true}}
function campaignEnemy(index){const rivals=Object.keys(decks).filter(k=>k!==deck),order=[0,1,2,0];return rivals[order[index]||0]}
function renderCampaign(){const grid=q('#campaignGrid'),done=Math.min(career.campaignStage,CAMPAIGN.length),progress=q('#campaignProgress');grid.innerHTML='';progress.innerHTML=`<b>${done} / ${CAMPAIGN.length} ETAPAS</b><i><span style="width:${done/CAMPAIGN.length*100}%"></span></i>`;CAMPAIGN.forEach((stage,index)=>{const unlocked=index<=career.campaignStage,completed=index<career.campaignStage,current=index===career.campaignStage&&career.campaignStage<CAMPAIGN.length,b=document.createElement('button');b.className='campaign-card '+(completed?'completed ':'')+(current?'current ':'')+(!unlocked?'locked':'');b.disabled=!unlocked;b.innerHTML=`<strong>${completed?'✓':unlocked?(index+1):'◆'}</strong><span><small>${stage.rank} • ${stage.difficulty==='easy'?'APRENDIZ':stage.difficulty==='expert'?'ESPECIALISTA':'NORMAL'}</small><b>${stage.n}</b><em>${stage.desc}</em></span><i>+${stage.reward}</i>`;b.onclick=()=>startCampaign(index);grid.append(b)})}
function openCampaign(){renderCampaign();q('#campaignModal').classList.remove('hidden')}
function closeCampaign(){q('#campaignModal').classList.add('hidden')}
function startCampaign(index){if(index>career.campaignStage||index>=CAMPAIGN.length)return;campaignMode=true;activeCampaignStage=index;closeCampaign();start()}
const TUTORIAL=[
 {t:'MONTE E MÃO',x:'Cada facção entra com 22 unidades e compra 10. Antes da partida você pode trocar até duas cartas.'},
 {t:'ESCOLHA UMA CARTA',x:'Toque numa carta da sua mão. Ela será ampliada e mostrará poder, tipo, fileira e habilidade.'},
 {t:'POSICIONE NA PRODUÇÃO',x:'A fileira correta ficará iluminada. Confirme em JOGAR ou toque diretamente na fileira destacada.'},
 {t:'ACOMPANHE OS EFEITOS',x:'Bônus, redução, proteção e compra aparecem sobre a fileira. A carta do rival também será revelada antes de entrar.'},
 {t:'CONSULTE A MESA',x:'Toque em qualquer carta pequena já jogada para ampliá-la. Use ÚLTIMA AÇÃO para rever tudo que aconteceu.'},
 {t:'HORA DE PASSAR',x:'Ao tocar em PASSAR você encerra suas jogadas. As cartas não usadas ficam na mão para as próximas rodadas.'},
 {t:'DUELO LOCAL',x:'No modo 2 JOGADORES, passe o celular após cada jogada. A mão seguinte fica escondida até o dono tocar em REVELAR.'}
];
function renderTutorial(){const s=TUTORIAL[tutorialStep];q('#tutorialNumber').textContent=(tutorialStep+1)+' / '+TUTORIAL.length;q('#tutorialTitle').textContent=s.t;q('#tutorialText').textContent=s.x;q('#nextTutorial').textContent=tutorialStep===TUTORIAL.length-1?'ENTENDI ✓':'PRÓXIMO ›'}
function openTutorial(){tutorialStep=0;renderTutorial();q('#tutorialModal').classList.remove('hidden')}
function closeTutorial(){q('#tutorialModal').classList.add('hidden');try{localStorage.setItem('forjaTutorialV21','ok')}catch(e){}}
function chooseFrame(){const game=q('#game'),old=FRAMES.map(x=>x.c);game.classList.remove(...old);const owned=FRAMES.filter(f=>career.ownedFrames.includes(f.c)),frame=career.selectedFrame==='random'?owned[Math.floor(Math.random()*owned.length)]:FRAMES.find(f=>f.c===career.selectedFrame)||owned[0];game.classList.add(frame.c);q('#frameName').textContent=frame.n}
function fill(target,data,enemy,bonuses){const box=q(target);box.innerHTML='';data.forEach((lane,i)=>{const r=document.createElement('div');r.className='row';r.innerHTML=`<span class="lane">${L[i]}<br><b>${laneValue(data,bonuses,i)}</b></span><div class="slots"></div>`;lane.forEach(c=>r.querySelector('.slots').append(make(c,enemy,true)));box.append(r)})}
function draw(){q('#game').style.setProperty('--deck-color',decks[deck].color);q('#game').style.setProperty('--enemy-color',decks[opponent].color);fill('#enemyRows',ai,true,aiBonus);fill('#playerRows',me,false,meBonus);const h=q('#hand'),side=gameMode==='local'?activeSide:'me',cards=side==='ai'?aiHand:hand;h.innerHTML='';cards.forEach(c=>{const card=make(c,side==='ai',false);card.onclick=()=>pickForSide(card,c,side);h.append(card)});const score=total(me,meBonus);matchStats.maxScore=Math.max(matchStats.maxScore,score);q('#playerScore').textContent=score;q('#enemyScore').textContent=total(ai,aiBonus);q('#round').textContent=round;q('#playerPile').textContent=meReserve.length;q('#enemyPile').textContent=aiReserve.length;q('#playerDiscard').textContent=meDiscard.length;q('#enemyDiscard').textContent=aiDiscard.length;q('#playerHand').textContent=hand.length;q('#enemyHand').textContent=aiHand.length;updateLeaderButton()}
function clearPick(){selected=null;selectedLane=null;q('#playCard').disabled=true;q('#playCard').textContent='SELECIONE UMA CARTA';['#playerRows','#enemyRows'].forEach(id=>[...q(id).children].forEach(r=>{r.classList.remove('target');r.onclick=null}))}
function validLanes(c,side='me'){const key=side==='me'?deck:opponent,ready=side==='me'?meLeaderReady:aiLeaderReady;if(c.n==='EMPILHADEIRA TURBO')return[0,1,2];if(key==='turbo'&&ready)return[0,1,2];return[c.l]}
function pickForSide(el,c,side='me'){if(busy||side!==activeSide&&gameMode==='local')return;sfx('select');selected=c;const lanes=validLanes(c,side),rows=q(side==='ai'?'#enemyRows':'#playerRows');selectedLane=lanes.length===1?lanes[0]:null;document.querySelectorAll('.hand .selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');q('#cardInfo').innerHTML=`<b>${c.n} • PODER ${c.p} • ${c.r}</b><span>${c.h}</span>`;q('#tip').textContent=lanes.length>1?'Escolha uma fileira iluminada.':'Destino: '+L[c.l]+'.';q('#playCard').disabled=lanes.length>1;q('#playCard').textContent=lanes.length>1?'ESCOLHA A FILEIRA':'JOGAR EM '+L[c.l];['#playerRows','#enemyRows'].forEach(id=>[...q(id).children].forEach(r=>{r.classList.remove('target');r.onclick=null}));[...rows.children].forEach((r,i)=>{r.classList.toggle('target',lanes.includes(i));r.onclick=lanes.includes(i)?()=>play(c,i):null})}
function pick(el,c){pickForSide(el,c,'me')}
function strongest(cards,filter=()=>true){return cards.filter(filter).sort((a,b)=>b.p-a.p)[0]||null}
function weakest(cards,filter=()=>true){return cards.filter(filter).sort((a,b)=>a.p-b.p)[0]||null}
function moveStrongest(own,toLane){let found=null,from=-1;own.forEach((lane,i)=>lane.forEach(c=>{if(i!==toLane&&/Máquina/.test(c.t)&&(!found||c.p>found.p)){found=c;from=i}}));if(found){own[from].splice(own[from].indexOf(found),1);own[toLane].push(found)}return found}
function damageStrongest(st,lane,amount){if(st.enemyShield[lane]){st.enemyShield[lane]=false;return'Proteção anulou a sabotagem'}const target=strongest(st.enemy[lane]);if(!target)return'Nenhum alvo rival';target.p=Math.max(0,target.p-amount);return target.n+' perdeu '+amount+' de poder'}
function drawReserve(side,predicate){const reserve=side==='me'?meReserve:aiReserve,index=reserve.findIndex(predicate);if(index<0)return null;const c=reserve.splice(index,1)[0];if(side==='me')hand.push(c);else aiHand.push(c);return c}
function recoverDiscard(side,predicate=()=>true){const pile=side==='me'?meDiscard:aiDiscard,c=strongest(pile,predicate);if(!c)return null;pile.splice(pile.indexOf(c),1);c.p=c.base;c.lastEffect='';if(side==='me')hand.push(c);else aiHand.push(c);return c}
function updateLeaderButton(){const b=q('#leaderPower');if(!b)return;const side=gameMode==='local'?activeSide:'me',used=side==='me'?meLeaderUsed:aiLeaderUsed;b.disabled=used;b.textContent=used?'✓ LÍDER USADO':'⚙ ATIVAR LÍDER'}
function activateLeader(side='me'){const st=state(side),used=side==='me'?meLeaderUsed:aiLeaderUsed;if(used)return'';let text='',target=null;if(st.key==='rio'){target=strongest(flat(st.own),x=>/Máquina/.test(x.t));if(target){target.p+=2;text=target.n+' recebeu regulagem do líder: +2'}}else if(st.key==='vulcao'){target=strongest(flat(st.own),x=>x.t==='Máquina pesada');if(target){target.p+=3;text=target.n+' recebeu potência de fundição: +3'}}else if(st.key==='elite'){target=weakest(flat(st.own),x=>/Máquina/.test(x.t));if(target){target.p+=4;target.repaired=true;text=target.n+' recebeu reparo do líder: +4'}}else if(st.key==='turbo'){text='Líder Turbo: a próxima carta pode mudar de fileira';if(side==='me')meLeaderReady=true;else aiLeaderReady=true}if(!text){if(side==='me'||gameMode==='local'){q('#tip').textContent='Jogue uma máquina compatível antes de ativar o líder.';sfx('select')}return''}if(side==='me')meLeaderUsed=true;else aiLeaderUsed=true;draw();if(side==='me'||gameMode==='local'){effect(text,side,'bonus','LÍDER');updateLeaderButton()}else recordAction(text,'ai','LÍDER');return text}
function maybeAiLeader(){if(aiLeaderUsed)return;if(playerPassed||round>=2||Math.random()<.3)activateLeader('ai')}
function applyAbility(c,side,lane){const st=state(side),key=st.key+':'+c.n;let text='',extra=false;
 if((side==='me'?mePending:aiPending)>0&&/Máquina/.test(c.t)){const bonus=side==='me'?mePending:aiPending;c.p+=bonus;if(side==='me')mePending=0;else aiPending=0;text='Lingote Quente: '+c.n+' recebeu +'+bonus}
 switch(key){
  case'rio:REGULADORA CNC':{const m=strongest(st.own[lane],x=>/Máquina/.test(x.t)&&x!==c);if(m){m.p+=3;text=m.n+' regulada: +3'}break}
  case'rio:TORNO CNC':if(st.own[lane].some(x=>x.n==='REGULADORA CNC')){c.p+=2;text='Torno CNC com reguladora: +2'}break;
  case'rio:INDEX GU800':text='INDEX produzirá +2 no fim da rodada';break;
  case'rio:EMPILHADEIRA TURBO':text='Empilhadeira posicionada em '+L[lane];break;
  case'rio:INSPETORA FINAL':st.shield[lane]=true;text=L[lane]+' protegida contra sabotagem';break;
  case'rio:SETUP PERFEITO':st.own[lane].forEach(x=>{if(x!==c)x.p+=1});text='Setup Perfeito: fileira inteira +1';break;
  case'rio:PONTE ROLANTE':{const m=moveStrongest(st.own,lane);text=m?m.n+' movida para '+L[lane]:'Nenhuma máquina para mover';break}
  case'rio:MANUTENÇÃO':{const m=weakest(flat(st.own),x=>/Máquina/.test(x.t));if(m){m.p+=4;m.repaired=true;text=m.n+' reparada: +4'}break}
  case'rio:OPERADORA COBALTO':{const m=weakest(flat(st.own),x=>x!==c&&/Máquina/.test(x.t));if(m){m.p+=3;text=m.n+' recebeu calibração cobalto: +3'}else{c.p+=3;text='Calibração própria: +3'}break}
  case'rio:HELENA CNC':{const r=drawReserve(side,x=>/Máquina/.test(x.t));text=r?'Helena programou a compra de '+r.n:'Nenhuma Máquina restante no monte';break}
  case'rio:GIOVANI':{const m=weakest(flat(st.own),x=>/Máquina/.test(x.t));if(m){m.p+=2;text=m.n+' recebeu ajuste de precisão: +2'}else{c.p+=2;text='Ajuste próprio de precisão: +2'}break}
  case'vulcao:MESTRE FUNDIDOR':st.own[lane].forEach(x=>{if(x!==c)x.p+=1});text='Fundição fortalecida: fileira +1';break;
  case'vulcao:FORNO VULCÃO':text='Forno Vulcão em potência máxima';break;
  case'vulcao:PRENSA TITÃ':if(st.enemy[lane].some(x=>x.t==='Máquina')){c.p+=2;text='Prensa contra máquina leve: +2'}break;
  case'vulcao:LINGOTE QUENTE':if(side==='me')mePending=3;else aiPending=3;text='Próxima máquina receberá +3';break;
  case'vulcao:GUINDASTE PESADO':{const r=drawReserve(side,x=>/Máquina/.test(x.t),lane);text=r?r.n+' puxada da reserva':'Reserva vazia';break}
  case'vulcao:QUALIDADE BRUTA':st.shield[lane]=true;text=L[lane]+' protegida contra redução';break;
  case'vulcao:TÊMPERA TOTAL':{let n=0;flat(st.own).filter(x=>x.t==='Material').forEach(x=>{const b=Math.max(0,x.p-x.base);if(b>0){x.p+=b;n++}});text=n?'Bônus de '+n+' materiais duplicados':'Nenhum material com bônus';break}
  case'vulcao:AÇO INCANDESCENTE':text=damageStrongest(st,lane,2);break;
  case'vulcao:GUARDIÃ DO ALTO-FORNO':text=damageStrongest(st,lane,3);break;
  case'vulcao:ASTRID DO AÇO':{let n=0;st.own[lane].forEach(x=>{if(x!==c){x.p+=1;n++}});text='Astrid fortaleceu '+n+' cartas da fileira: +1';break}
  case'vulcao:JONATHAN':text=damageStrongest(st,lane,2);break;
  case'turbo:PILOTO TURBO':{const x=strongest(st.own[lane],y=>y.t==='Logística'&&y!==c);if(x){x.p+=2;text=x.n+' reativada: +2'}break}
  case'turbo:EMPILHADEIRA ELÉTRICA':if((side==='me'?lastMe:lastAi)?.n==='PALLETS URGENTES'){c.p+=2;text='Combo com Pallets: +2'}break;
  case'turbo:DOCA EXPRESSA':extra=true;text='Doca Expressa: jogue outra carta';break;
  case'turbo:PONTE ROLANTE':{const x=moveStrongest(st.own,lane);text=x?x.n+' movida entre fileiras':'Nenhuma máquina para mover';break}
  case'turbo:ESTOQUISTA':{const r=drawReserve(side,x=>x.t==='Material'||x.t==='Carga',lane);text=r?'Carta comprada: '+r.n:'Nenhum material na reserva';break}
  case'turbo:PALLETS URGENTES':{const n=flat(st.own).filter(x=>x.t==='Logística').length;c.p+=n;text='Pallets: +'+n+' por logística';break}
  case'turbo:CAMINHÃO DE CARGA':{const near=lane===0?1:lane-1;st.bonus[near]+=6;text=L[near]+' recebeu +6';break}
  case'turbo:ROTA OTIMIZADA':{let n=0;flat(st.own).filter(x=>x.t==='Carga').forEach(x=>{x.p+=2;n++});text=n+' cargas receberam +2';break}
  case'turbo:PILOTO SOLAR':{const x=weakest(flat(st.own),y=>y!==c&&(y.t==='Logística'||y.l===1));if(x){x.p+=3;text=x.n+' recebeu impulso solar: +3'}else{c.p+=3;text='Impulso solar próprio: +3'}break}
  case'turbo:LARA EXPRESSA':{const r=drawReserve(side,()=>true);text=r?'Lara acelerou a compra de '+r.n:'O monte está vazio';break}
  case'turbo:JÚLIO':{const x=weakest(flat(st.own),y=>y!==c&&(y.t==='Logística'||y.l===1));if(x){x.p+=2;text=x.n+' recebeu rota segura: +2'}else{c.p+=2;text='Júlio abriu a rota: +2'}break}
  case'elite:TÉCNICA ELITE':{const m=weakest(flat(st.own),x=>/Máquina/.test(x.t)&&x!==c);if(m){m.p+=4;m.repaired=true;st.shield[lane]=true;text=m.n+' reparada +4 e protegida'}break}
  case'elite:OFICINA MÓVEL':{let n=0;flat(st.own).filter(x=>x.t==='Equipe').forEach(x=>{x.p+=1;n++});text=n+' equipes receberam +1';break}
  case'elite:LUBRIFICAÇÃO':{const m=strongest(flat(st.own),x=>/Máquina/.test(x.t));if(m){m.p+=1;m.lubed=true;text=m.n+' lubrificada: +1 agora e no fim'}break}
  case'elite:CALIBRADOR DIGITAL':{const b=Math.max(1,...flat(st.own).filter(x=>x!==c).map(x=>Math.max(0,x.p-x.base)));c.p+=b;text='Calibrador copiou bônus +'+b;break}
  case'elite:SOLDADOR':{const r=drawReserve(side,x=>/Máquina/.test(x.t),lane);text=r?'Máquina recuperada: '+r.n:'Nenhuma máquina na reserva';break}
  case'elite:PEÇA SOBRESSALENTE':st.shield[lane]=true;text=L[lane]+' protegida contra quebra';break;
  case'elite:MECÂNICO CHEFE':{let n=0;flat(st.own).filter(x=>x.repaired).forEach(x=>{x.p+=2;n++});text=n+' máquinas reparadas receberam +2';break}
  case'elite:REPARO URGENTE':{const m=weakest(flat(st.own),x=>/Máquina/.test(x.t));if(m){m.p+=3;m.repaired=true}extra=true;text=(m?m.n+' restaurada +3. ':'')+'Jogue novamente';break}
  case'elite:ENGENHEIRA VIOLETA':{const x=weakest(flat(st.own),y=>y!==c&&/Máquina/.test(y.t));if(x){x.p+=3;text=x.n+' recebeu reparo violeta: +3'}else{c.p+=3;text='Reparo violeta próprio: +3'}break}
  case'elite:SOFIA HIDRÁULICA':{const r=recoverDiscard(side);text=r?'Sofia recuperou '+r.n+' do descarte':'O descarte ainda está vazio';break}
  case'elite:GABRIEL':{const x=weakest(flat(st.own),y=>y!==c&&y.l===2);if(x){x.p+=2;text=x.n+' recebeu diagnóstico noturno: +2'}else{c.p+=2;text='Diagnóstico próprio: +2'}break}
 }
 const resolved=text||c.n+' ativada';c.lastEffect=resolved;if(side==='me')lastMe=c;else lastAi=c;return{text:resolved,extra}
}
function showLocalTurn(side){activeSide=side;busy=true;clearPick();q('#hand').innerHTML='';q('#turnTitle').textContent=side==='me'?'VEZ DO JOGADOR 1':'VEZ DO JOGADOR 2';q('#turnText').textContent='Passe o celular para '+decks[side==='me'?deck:opponent].name+'. A mão permanece escondida até a confirmação.';q('#turnModal').classList.remove('hidden')}
function localAfterAction(side,extra=false){const passed=side==='me'?playerPassed:aiPassed,other=side==='me'?'ai':'me',otherPassed=other==='me'?playerPassed:aiPassed;if(playerPassed&&aiPassed){busy=false;return setTimeout(endRound,350)}if(extra&&!passed){busy=false;draw();q('#cardInfo').innerHTML='<b>JOGADA EXTRA</b><span>Você pode jogar outra carta antes de passar o celular.</span>';return}if(otherPassed&&!passed){activeSide=side;busy=false;draw();clearPick();q('#tip').textContent='O outro jogador passou. Continue ou encerre a rodada.';return}showLocalTurn(other)}
function play(c=selected,lane=selectedLane){const side=gameMode==='local'?activeSide:'me',cards=side==='me'?hand:aiHand,passed=side==='me'?playerPassed:aiPassed,own=side==='me'?me:ai,key=side==='me'?deck:opponent;if(busy||passed||!c||lane===null||!cards.includes(c))return;busy=true;showBattleCard(c,side,lane,()=>{if(key==='turbo'&&(side==='me'?meLeaderReady:aiLeaderReady)){if(side==='me')meLeaderReady=false;else aiLeaderReady=false;updateLeaderButton()}cards.splice(cards.indexOf(c),1);if(side==='me'&&FRIENDS.has(c.n))matchStats.friendPlayed=true;c.playedLane=lane;own[lane].push(c);clearPick();sfx('card');const result=applyAbility(c,side,lane);if(!cards.length){if(side==='me')playerPassed=true;else aiPassed=true}draw();effect(result.text,side,result.text.includes('perdeu')?'hit':'bonus',c.n);laneEffect(side,lane,result.text);const rows=q(side==='ai'?'#enemyRows':'#playerRows'),pc=rows.children[lane].querySelector('.card:last-child');if(pc){pc.classList.add('attack');if(SPECIALS.has(c.n))pc.classList.add('legendary-land')}if(gameMode==='local')return localAfterAction(side,result.extra);if(result.extra){busy=false;if(playerPassed)return continuePassedRound();q('#cardInfo').innerHTML='<b>JOGADA EXTRA</b><span>Escolha outra carta antes da resposta rival.</span>';return}if(playerPassed){busy=false;return continuePassedRound()}setTimeout(()=>enemyMove(false),700)})}
function aiLanes(c){if(c.n==='EMPILHADEIRA TURBO'||(opponent==='turbo'&&aiLeaderReady))return[0,1,2];return[c.l]}
function aiScore(c,lane){const own=laneValue(ai,aiBonus,lane),rival=laneValue(me,meBonus,lane),gap=rival-own;let score=c.p;if(gap>0&&gap<=c.p+5)score+=8;if(gap<0)score+=Math.max(0,4-Math.abs(gap)/4);if(/perde|redução|sabotagem/i.test(c.h)&&me[lane].length)score+=5;if(/\+|fortalece|recebe/i.test(c.h)&&ai[lane].length)score+=3;if(/protege/i.test(c.h)&&me[lane].length)score+=2;if(FRIENDS.has(c.n))score+=2;return score}
function chooseAiPlay(){if(!aiHand.length)return null;let choices=[];aiHand.forEach((c,index)=>aiLanes(c).forEach(lane=>choices.push({c,index,lane,score:aiScore(c,lane)+Math.random()*1.5})));let pick;if(difficulty==='easy')pick=choices[Math.floor(Math.random()*choices.length)];else{choices.sort((a,b)=>b.score-a.score);pick=difficulty==='expert'?choices[0]:choices[Math.floor(Math.random()*Math.min(3,choices.length))]}aiHand.splice(pick.index,1);if(opponent==='turbo'&&aiLeaderReady)aiLeaderReady=false;return pick}
function shouldAiPass(){const own=total(ai,aiBonus),rival=total(me,meBonus),gap=rival-own;if(!aiHand.length)return true;if(playerPassed)return own>=rival||(gap>24&&aiHand.length<=3&&losses===0);if(own>rival+8&&aiHand.length+1<hand.length)return true;if(gap>26&&aiHand.length<=3&&losses===0)return true;return false}
