function passRound(){if(busy)return;if(gameMode==='local'){const side=activeSide,already=side==='me'?playerPassed:aiPassed;if(already)return;if(side==='me')playerPassed=true;else aiPassed=true;clearPick();recordAction('Encerrou as jogadas desta rodada.',side,'PASSAR');q('#cardInfo').innerHTML='<b>JOGADOR PASSOU</b><span>O outro jogador pode continuar usando sua mão.</span>';sfx('select');return localAfterAction(side)}if(playerPassed)return;playerPassed=true;clearPick();recordAction('Você encerrou suas jogadas. A rival ainda pode responder.','me','PASSAR');q('#cardInfo').innerHTML='<b>VOCÊ PASSOU</b><span>A rival ainda pode usar as cartas restantes.</span>';sfx('select');continuePassedRound()}
