function chooseTrackIndex(){const owned=career.ownedTracks.filter(i=>TRACK_INFO[i]);if(career.selectedTrack>=0)return career.selectedTrack;let next=owned[0];if(owned.length>1)while(next===trackIndex)next=owned[Math.floor(Math.random()*owned.length)];return next}
function chooseTrack(){const music=q('#music');trackIndex=chooseTrackIndex();if(!music)return trackIndex;music.src=TRACKS[trackIndex];music.load();return trackIndex}
