function endGame(){q('#game').classList.add('hidden');const won=wins>=2,bonus=difficulty==='expert'?50:difficulty==='normal'?20:0,c=CONTRACTS.find(x=>x.id===career.selectedContract),stage=campaignMode?CAMPAIGN[activeCampaignStage]:null;career.matches++;if(won)career.wins++;career.lastContractBonus=contractDone(won)?c.reward:0;career.lastCampaignBonus=stage&&won?stage.reward:0;if(stage&&won&&activeCampaignStage===career.campaignStage)career.campaignStage=Math.min(CAMPAIGN.length,career.campaignStage+1);career.lastReward=(won?100+bonus:35)+career.lastContractBonus+career.lastCampaignBonus;career.scrap+=career.lastReward;saveProgress();updateCareer();const fx=q(won?'#victoryFx':'#defeatFx');fx.classList.remove('hidden');setTimeout(()=>{fx.classList.add('hidden');revealResult(won)},3200)}
